// CONTRACT shared by all lanes (sim, render, ui, art). Owner: manager. Lanes do not edit this file;
// need a change -> say so in your final report.
// Units: world px (map is 1000 x 1600, portrait, y down); time = sim seconds; money = coins (integers).

// ---------- map (src/data/city1.json, owner: manager) ----------
export interface MapNode { id: string; x: number; y: number }
export interface MapEdge { a: string; b: string; kind: 'main' | 'street' | 'sand' | 'check' | 'gate' } // street, sand = slower; check = security checkpoint (slowest); gate = crowd-flow gate (main speed, crawls inside LevelDef.gateWindows)
export interface Decor { key: AssetKey; x: number; y: number; scale?: number } // static buildings/trees
export interface SiteSpot { id: string; nodeId: string; x: number; y: number; slots: { x: number; y: number }[] } // cabin slot world positions
export interface CityMap {
  id: string; name: string; width: number; height: number;
  depotNodeId: string; depot: { x: number; y: number }; bg?: string; // painted background key, default 'bg'
  nodes: MapNode[]; edges: MapEdge[]; spots: SiteSpot[]; decor: Decor[];
  dumps?: { nodeId: string; x: number; y: number }[]; // satellite dump stations: a truck that finished pumping empties its tank at the fastest of depot + dumps (no stock/wash there); x/y = marker position
}

// ---------- level data (src/data/levels.json + economy.json, owner: sim lane) ----------
export type SiteType = 'construction' | 'wedding' | 'beach' | 'ceremony' | 'show';
export interface SiteDef {
  id: string; type: SiteType; name: string; // Hebrew display name
  spotId: string; // SiteSpot in the map
  openAt: number; closeAt: number; // sim seconds from day start
  usage: [number, number][]; // piecewise-linear [t, liters per second at the whole site], t relative to openAt
  fee: number; // paid at close if site survived
  serviceTip: number; // per cabin emptied
  overflowFinePerSec: number;
}
export interface UnlockDef { kind: 'site' | 'equipment' | 'vehicle' | 'city' | 'mechanic'; name: string; desc: string; icon: AssetKey }
export interface LevelDef {
  id: number; title: string; dayLength: number; // sim seconds
  city?: string; // CityMap id ('city-beach' | 'city-capital' | 'city-shows' | 'city-industry' | 'city-valley' | 'city-desert' | 'city-night'), default 'city-real'
  maxTank?: number; // small trucks only (rough roads): tank capped at this many liters whatever tank upgrade was bought
  night?: boolean; // night shift: truck drives at the 'lights' upgrade value x speed (dark streets are slow)
  washSec?: number; // water scarcity: seconds to wash one dirty cabin at the depot (default ECON.wash.sec)
  gateWindows?: [number, number][]; // sim-second [from, to) windows when 'gate' edges crawl (ECON.gateSpeedMult); none = gates are plain roads
  sites: SiteDef[];
  coinTarget: number; // 3rd star
  unlock: UnlockDef; // shown on this level's end card
}
export interface UpgradeDef { id: 'pump' | 'tank' | 'cabin' | 'lights' | 'engine' | 'fleet'; name: string; desc: string; costs: number[]; values: number[]; fromLevel?: number } // values[i] = stat at upgrade level i (values[0] = start)

// ---------- persistent save (localStorage 'bereshit.save.v1') ----------
export interface Save { coins: number; level: number; stars: Record<number, number>; upgrades: { pump: number; tank: number; cabin: number; lights: number; engine: number; fleet: number } }

// ---------- live state (sim owns + mutates; render/ui read only) ----------
export type TruckJob = 'idle' | 'toSite' | 'pumping' | 'toDepot' | 'dumping' | 'delivering' | 'collecting'; // collecting = driving to a finished site to load its cabins
export interface Truck {
  id: string; name: string; job: TruckJob;
  path: string[]; // node ids of current route, path[0] = from
  seg: number; segT: number; // index into path + 0..1 along that edge
  x: number; y: number; angle: number; // world pose, sim-updated every step
  tank: number; tankCap: number; pumpRate: number; speed: number; // liters, L/s, px/s
  targetSiteId: string | null; carrying: number; // cabins on board
}
export interface Cabin { id: string; siteId: string | null; slot: number; fill: number; capacity: number; washT: number } // siteId null = in depot stock; washT > 0 = dirty, seconds of washing left; cabins of a closed site stay there until a truck collects them
export interface SiteState { def: SiteDef; open: boolean; closed: boolean; overflowSec: number; earned: number; x: number; y: number }
export type GameEvent =
  | { kind: 'siteOpen' | 'siteClose' | 'overflowStart' | 'overflowEnd'; siteId: string }
  | { kind: 'cabinEmptied'; siteId: string; cabinId: string; tip: number }
  | { kind: 'delivered'; siteId: string; count: number }
  | { kind: 'collected'; siteId: string; count: number }
  | { kind: 'paid'; siteId: string; amount: number }
  | { kind: 'fine'; siteId: string; amount: number }
  | { kind: 'washed'; cabinId: string }
  | { kind: 'dayEnd' };
export interface GameState {
  level: LevelDef; map: CityMap; time: number; over: boolean;
  coinsStart: number; coins: number; // coins = live wallet during the day
  trucks: Truck[]; cabins: Cabin[]; sites: SiteState[];
  events: GameEvent[]; // events produced by the LAST step() call only
}

export type Command =
  | { type: 'service'; truckId: string; siteId: string } // drive, empty cabins until tank full / all empty, return, dump
  | { type: 'deliver'; truckId: string; siteId: string; count: number } // load cabins at depot, drive, place in free slots, return
  | { type: 'collect'; truckId: string; siteId: string } // client finished: drive to the closed site, load its cabins, bring them to the depot to wash
  | { type: 'recall'; truckId: string }; // abort, drive back to depot
export interface CommandResult { ok: boolean; reason?: string } // reason = Hebrew, shown to the player
export interface DayResult { levelId: number; stars: 0 | 1 | 2 | 3; earned: number; fines: number; overflowSec: number; coinTarget: number }

// sim/index.ts exports (sim lane implements):
//   createDay(level: LevelDef, map: CityMap, save: Save): GameState
//   step(s: GameState, dt: number): void            // deterministic, clears + refills s.events
//   command(s: GameState, c: Command): CommandResult
//   dayResult(s: GameState): DayResult
//   applyResult(save: Save, r: DayResult): Save      // pure
//   buyUpgrade(save: Save, id: UpgradeDef['id']): { ok: boolean; save: Save; reason?: string }
//   LEVELS: LevelDef[]; UPGRADES: UpgradeDef[]; newSave(): Save

// ---------- render (render lane implements src/render/index.ts) ----------
export type Selection = { kind: 'site' | 'truck' | 'depot'; id: string } | null;
export interface RenderApi {
  mount(el: HTMLElement, map: CityMap): Promise<void>;
  update(s: GameState, frameDt: number): void; // called every frame after step(); also consumes s.events for FX
  onSelect(cb: (sel: Selection) => void): void;
  focus(x: number, y: number, dyPx?: number): void;
}
//   export function createRender(): RenderApi

// ---------- ui (ui lane implements src/ui/index.ts) ----------
export interface UiHandlers {
  command(c: Command): CommandResult;
  startDay(): void; // from the pre-day / end card
  restart(): void; // wipe progress, back to day 1
  buyUpgrade(id: UpgradeDef['id']): { ok: boolean; reason?: string };
  setSpeed(x: 1 | 2 | 3): void;
  focus(x: number, y: number, dyPx?: number): void; // edge-arrow tap -> camera
}
export interface UiApi {
  mount(root: HTMLElement, h: UiHandlers): void;
  update(s: GameState): void; // every frame; keep DOM writes cheap (diff)
  select(sel: Selection, s: GameState): void;
  showDayStart(level: LevelDef, save: Save): void;
  showDayEnd(r: DayResult, save: Save, next: LevelDef | undefined): void; // includes shop + next-unlock teaser
}
//   export function createUi(): UiApi

// ---------- assets (art lane, game/public/assets/, manifest.json) ----------
// manifest.json: { [key in AssetKey]?: { file: string; w: number; h: number; ax: number; ay: number } } (ax/ay = anchor 0..1, ground contact)
// Missing key -> render draws a placeholder shape. Truck faces RIGHT (render rotates/flips). View: 3/4 top-down, dir B look.
export type AssetKey =
  | 'truck' | 'truck-wheel' | 'cabin' | 'cabin-door-open' | 'depot' | 'wash-bay'
  | 'site-construction' | 'crane' | 'site-wedding' | 'wedding-arch' | 'wedding-table'
  | 'building-1' | 'building-2' | 'building-3' | 'building-4' | 'building-5' | 'building-6'
  | 'tree-1' | 'tree-2' | 'person-1' | 'person-2' | 'person-3' | 'worker' | 'bride' | 'groom'
  | 'icon-coin' | 'icon-star' | 'icon-pump' | 'icon-tank' | 'icon-cabin' | 'icon-luxury-trailer' | 'fx-splash' | 'fx-dust'
  | 'logo-white' | 'logo-navy';
